function compute_k_M1_pol_Watkins2007_IL12_TAM_reprogramming(params, inputs)
    k = params["k_M1_pol"]
    t_half_days = log(2) / k
    return t_half_days  # days
end

function compute_k_CCL2_sec_bcproxy_yoshimura2023(params, inputs)
    k = params["k_CCL2_sec"]
    cells = inputs["MDA_MB231_cell_count"]
    time_days = inputs["MDA_MB231_time_interval_48h"] / 24.0
    mw = inputs["CCL2_molecular_weight"]
    nmol = k * cells * time_days
    mass_g = nmol * 1e-9 * mw
    mass_ng = mass_g * 1e9
    return mass_ng  # nanograms
end

function compute_k_C1_growth_pdac_tumor_doubling_jang2015(params, inputs)
    k = params["k_C1_growth"]  # 1/day
    return log(2) / k  # in days
end

function compute_q_Treg_T_in_PDAC_Tang2014(params, inputs)
    q = params["q_Treg_T_in"]
    t_doubling = inputs["Treg_doubling_time_mean"]
    k_per_day = log(2) / t_doubling
    k_per_min = k_per_day / (24.0 * 60.0)
    V_ref = 1.0
    ratio = q * V_ref / k_per_min
    return ratio
end

function compute_k_CCL2_sec_Steube1999_proxy(params, inputs)
    k = params["k_CCL2_sec"]
    MW = 8700.0
    mcp1_pg = k * 1e6 * 1.0 / (1e-12 / MW * 1e9)
    return mcp1_pg  # pg/mL per 1e6 cells
end

function compute_q_Treg_T_in_extravasation_PDAC(params, inputs)
    q = params["q_Treg_T_in"]
    tau_hr = inputs["migration_time_4h_hr"]
    tau_min = tau_hr * 60.0
    V_T_ref = 1.0
    k_in = q * V_T_ref
    f_treg = 1.0 - exp(-k_in * tau_min)
    return f_treg
end


# Analytical solution for first-order decay: du/dt = -k*u => u(t) = u₀ * exp(-k*t)
function simulate_k_apsc_death_melatoninPSC_Estaras2021(k_apsc_death)
    d = DATA["k_apsc_death_melatoninPSC_Estaras2021"]
    t_final = d.t_span[2]
    y0 = d.y0[1]
    return y0 * exp(-k_apsc_death * t_final)
end

function compute_q_CD8_T_in_yorty2007_sv11_brain_tumor(params, inputs)
    q = params["q_CD8_T_in"]
    V_ref = inputs["reference_tumor_volume"]
    k_in_per_min = q * V_ref
    t_peak_min = 3.0 / k_in_per_min
    t_peak_days = t_peak_min / (24.0 * 60.0)
    return t_peak_days  # days
end

function compute_k_psc_activation_apte1998(params, inputs)
    k = params["k_psc_activation"]
    t_days = 1.0 / k
    t_hours = t_days * 24.0
    return t_hours  # hours
end

function compute_k_Mac_rec_PDAC_M1_recruitment_Gu2023(params, inputs)
    k_rec = params["k_Mac_rec"]
    A = inputs["HPF_area_400x_microscope"]
    thickness = inputs["section_thickness_histology"]
    t_min = inputs["macrophage_half_life_min"]
    t_max = inputs["macrophage_half_life_max"]
    t_half = (t_min + t_max) / 2.0
    k_death = log(2) / t_half
    V_mm3 = A * thickness
    V_mL = V_mm3 / 1000.0
    density = k_rec / k_death
    M1_per_HPF = density * V_mL
    return M1_per_HPF  # cells per HPF
end

function compute_N_IL2_CD4_division_destiny_Gett1998(params, inputs)
    N = params["N_IL2_CD4"]
    return N
end

function compute_k_MDSC_rec_recruitment_pericyte_MDSC_Hong2015(params, inputs)
    k_rec = params["k_MDSC_rec"]
    cell_density = inputs["tumor_cell_density"]
    half_life = inputs["MDSC_half_life"]
    k_death = log(2) / half_life
    frac = k_rec / (k_death * cell_density) * 100.0
    return frac  # percent
end

function compute_k_MDSC_rec_oscc_ccl2_oo2022(params, inputs)
    k_rec = params["k_MDSC_rec"]
    V_eff = inputs["imaging_volume_per_field"]
    t_hours = inputs["migration_time_9h"]
    t_days = t_hours / 24.0
    migrated = k_rec * V_eff * t_days
    return migrated  # cells
end

function compute_n_CD8_clones_Meng2023_PDAC(params, inputs)
    n_clones = params["n_CD8_clones"]
    n_tumors = inputs["n_PDAC_tumors_Meng2023"]
    total_tr = n_clones * n_tumors
    return total_tr
end

function compute_N_IL2_CD8_division_generations_castro2012(params, inputs)
    N = params["N_IL2_CD8"]
    fold_increase = 2.0 ^ N
    return fold_increase
end

function compute_k_Mac_rec_PDAC_TAM_recruitment_Chen2015(params, inputs)
    # Numeric implementation; units are handled externally in the inference engine
    k_rec = params["k_Mac_rec"]
    tau = inputs["macrophage_res_time_days"]
    H = inputs["H_CCL2_PD"]  # dimensionless
    # Effective loss rate 1/day
    k_loss = log(2.0) / tau
    rho = (k_rec / k_loss) * H
    return rho
end

function compute_k_apsc_death_RA_Xiao2015(params, inputs)
    k = params["k_apsc_death"]
    t_half = log(2) / k
    return t_half  # days
end

function compute_q_CD8_T_in_extravasation_boissonnas2007(params, inputs)
    q = params["q_CD8_T_in"]
    CD8_C = inputs["OT1_injected"]
    t_half_h = inputs["CD8_eff_half_life"]
    k_death = log(2) / (t_half_h * 60.0)
    thickness_mm = inputs["section_thickness_um"] / 1000.0
    rho = q * CD8_C / k_death / 1000.0
    d_2d = rho * thickness_mm
    return d_2d  # cells/mm^2
end

function compute_k_CCL2_sec_Fujita2010_PrSC(params, inputs)
    k = params["k_CCL2_sec"]
    N_cells = inputs["n_cells_prsc"]
    t_h = inputs["incubation_time_hours"]
    V_ml = inputs["V_medium_ml"]
    MW = 8.7e3
    days = t_h / 24.0
    nmol = k * N_cells * days
    mass_g = nmol * 1e-9 * MW
    mass_pg = mass_g * 1e12
    conc = mass_pg / V_ml
    return conc  # pg/mL
end

function compute_k_M1_pol_repolarization_horhold2020(params, inputs)
    k = params["k_M1_pol"]
    t_half_days = log(2) / k
