function compute_q_Treg_T_in_Tremblay2017_MRIcelltracking(params, inputs)
    q = params["q_Treg_T_in"]
    V_ref = inputs["V_T_ref"]
    k_extrav_per_min = q * V_ref
    t_half_min = log(2) / k_extrav_per_min
    t_half_h = t_half_min / 60.0
    return t_half_h  # hours
end


